//! Raw FFmpeg bindings, generated by `build.rs` from `wrapper.h`, plus the
//! function-like macros bindgen can't translate.

#![allow(
    dead_code,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    clippy::all,
    clippy::pedantic,
    unnecessary_transmutes,
    unsafe_op_in_unsafe_fn
)]

include!(concat!(env!("OUT_DIR"), "/ffmpeg.rs"));

/// `AV_NOPTS_VALUE`: no timestamp.
pub const AV_NOPTS_VALUE: i64 = i64::MIN;

/// `MKTAG`/`FFERRTAG`: FFmpeg's own error codes are negated four-char tags.
const fn fferrtag(tag: &[u8; 4]) -> i32 {
    -((tag[0] as i32) | ((tag[1] as i32) << 8) | ((tag[2] as i32) << 16) | ((tag[3] as i32) << 24))
}

/// `AVERROR_EOF`: end of file, or a decoder fully drained.
pub const AVERROR_EOF: i32 = fferrtag(b"EOF ");
/// `AVERROR_INVALIDDATA`.
pub const AVERROR_INVALIDDATA: i32 = fferrtag(b"INDA");
/// `AVERROR_DECODER_NOT_FOUND`.
pub const AVERROR_DECODER_NOT_FOUND: i32 = fferrtag(&[0xF8, b'D', b'E', b'C']);

/// The C library's `EAGAIN`, which FFmpeg returns negated.
#[cfg(any(target_os = "macos", target_os = "ios"))]
const EAGAIN: i32 = 35;
#[cfg(not(any(target_os = "macos", target_os = "ios")))]
const EAGAIN: i32 = 11;

/// `AVERROR(EAGAIN)`: send more input, or read output first.
pub const AVERROR_EAGAIN: i32 = -EAGAIN;

/// `av_q2d`.
pub fn q2d(rational: AVRational) -> f64 {
    f64::from(rational.num) / f64::from(rational.den)
}
